import XCTest

final class DriverTests: XCTestCase {

    func testSendStatusUpdate() throws {
        let app = XCUIApplication(bundleIdentifier: "im.vector.app")
        app.activate()

        let room = app.descendants(matching: .any).matching(
            NSPredicate(format: "label BEGINSWITH %@", "Project Phoenix")
        ).firstMatch
        XCTAssertTrue(room.waitForExistence(timeout: 30), "Project Phoenix row not found")
        room.tap()
        sleep(3)

        print("TREE_AFTER_OPEN_BEGIN")
        print(app.debugDescription)
        print("TREE_AFTER_OPEN_END")

        let composer = app.textViews.firstMatch
        let composerExists = composer.waitForExistence(timeout: 15)
        print("COMPOSER_TEXTVIEW_EXISTS=\(composerExists)")
        if !composerExists {
            let fallback = app.textFields.firstMatch
            XCTAssertTrue(fallback.waitForExistence(timeout: 5), "composer not found")
            fallback.tap()
            fallback.typeText("status update")
        } else {
            composer.tap()
            composer.typeText("status update")
        }
        sleep(1)

        print("TREE_AFTER_TYPE_BEGIN")
        print(app.debugDescription)
        print("TREE_AFTER_TYPE_END")

        let sendButton = app.buttons["Send"].firstMatch
        XCTAssertTrue(sendButton.waitForExistence(timeout: 10), "Send button not found")
        sendButton.tap()
        sleep(3)

        print("TREE_AFTER_SEND_BEGIN")
        print(app.debugDescription)
        print("TREE_AFTER_SEND_END")
    }
}

