import XCTest

final class DriverTests: XCTestCase {

    func testSendStatusUpdate() throws {
        let app = XCUIApplication(bundleIdentifier: "im.vector.app")
        app.activate()
        sleep(2)

        let contextMenuOpen = app.buttons["Mark as read"].exists || app.staticTexts["Mark as read"].exists
            || app.descendants(matching: .any).matching(NSPredicate(format: "label == %@", "Mark as read")).firstMatch.exists
        print("CONTEXT_MENU_OPEN=\(contextMenuOpen)")
        if contextMenuOpen {
            app.coordinate(withNormalizedOffset: CGVector(dx: 0.5, dy: 0.04)).tap()
            sleep(2)
        }

        let roomScreen = app.otherElements["RoomVCView"]
        if !roomScreen.waitForExistence(timeout: 3) {
            let room = app.descendants(matching: .any).matching(
                NSPredicate(format: "label BEGINSWITH %@", "Project Phoenix")
            ).firstMatch
            XCTAssertTrue(room.waitForExistence(timeout: 30), "Project Phoenix row not found")
            room.tap()
            sleep(3)
        }

        let composer = app.textViews["GrowingTextView"].firstMatch
        XCTAssertTrue(composer.waitForExistence(timeout: 15), "composer not found")
        composer.tap()
        sleep(1)
        composer.typeText("status update")
        sleep(1)

        print("TREE_AFTER_TYPE_BEGIN")
        print(app.debugDescription)
        print("TREE_AFTER_TYPE_END")

        let sendButton = app.descendants(matching: .any).matching(
            NSPredicate(format: "(identifier CONTAINS[c] 'send' OR label CONTAINS[c] 'send') AND elementType == %d", XCUIElement.ElementType.button.rawValue)
        ).firstMatch
        XCTAssertTrue(sendButton.waitForExistence(timeout: 10), "Send button not found")
        print("SEND_LABEL=\(sendButton.label) ID=\(sendButton.identifier)")
        sendButton.tap()
        sleep(3)

        print("TREE_AFTER_SEND_BEGIN")
        print(app.debugDescription)
        print("TREE_AFTER_SEND_END")
    }
}

